"""Return an ordered keep mask and one finite margin per proposed call."""
# Validate inputs
if not all(isinstance(x, np.ndarray) for x in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("Inputs must be numpy arrays")
if logp_with_result.ndim != 2 or logp_call_only.ndim != 2 or logp_no_call.ndim != 2:
    raise ValueError("Input matrices must be 2-dimensional")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Input matrices must have the same shape")
if logp_with_result.size == 0 or logp_call_only.size == 0 or logp_no_call.size == 0:
    raise ValueError("Input matrices must not be empty")
if not np.isfinite(logp_with_result).all() or not np.isfinite(logp_call_only).all() or not np.isfinite(logp_no_call).all():
    raise ValueError("All elements must be finite")
if (logp_with_result > 0).any() or (logp_call_only > 0).any() or (logp_no_call > 0).any():
    raise ValueError("All elements must be nonpositive")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter cannot be boolean")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be finite and nonnegative")

# Compute per-candidate margins
sum_with = np.sum(logp_with_result, axis=1)
sum_call = np.sum(logp_call_only, axis=1)
sum_no = np.sum(logp_no_call, axis=1)
improvement_no_call = sum_with - sum_no
improvement_call_only = sum_with - sum_call
margin = np.minimum(improvement_no_call, improvement_call_only)
keep = margin > tau_filter
return keep, margin.astype(np.float64)
